const socket = io({ ackTimeout: 5000, retries: 0 });
async function sum(values: number[]): Promise<number> {
  try {
    return await socket.emitWithAck('sum', values);   // ack is the reply
  } catch (err) {
    throw new CallError('reply timeout', { cause: err });
  }
}
